{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "In rabbits, [14C]dalbavancin-derived radioactivity in CSF was low and measurable only at 12 and 24 h after dosing, indicating impermeable BBB permeability for this lipoglycopeptide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "In a rabbit meningitis model, oritavancin showed only 1–5% CSF penetration, demonstrating poor CNS access for a closely related lipoglycopeptide under the same disease condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In a rabbit S. pneumoniae meningitis model, oritavancin CSF/plasma ratio was 5%, confirming poor CNS penetration despite meningeal inflammation.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large lipoglycopeptide antibiotic; direct evidence from dalbavancin and oritavancin in meningitis models shows minimal CSF penetration (1–5% or below), and the physicochemical prior indicates negligible passive BBB permeability. Therefore meaningful CNS access is not supported.",
  "evidence_gaps": [
    "No direct CSF or brain PK data for the exact query molecule, but close lipoglycopeptide analogues with direct meningitis-model data provide strong transfer.",
    "No human CSF penetration data for the query; available animal meningitis models are the most relevant experimental context.",
    "Potential active uptake mechanisms are unlikely given the molecule's size and polarity and were not demonstrated."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

